/**
 * Turns `tokens.ts` into `styles/tokens.css`: CSS variables for both themes
 * plus the Tailwind v4 `@theme` mapping. Run via `pnpm --filter @truckbuck/ui tokens`.
 * Explicit `.ts` import: Node runs this file directly (type stripping).
 */
import {
  breakpoints,
  colorRoles,
  fontFamilies,
  layout,
  motion,
  radii,
  shadows,
  spacingBase,
  type ThemeName,
  themes,
  typeScale,
  zIndex,
} from "./tokens.ts";

const HEADER = `/*
 * @generated by packages/ui/scripts/generate-tokens.ts from src/tokens/tokens.ts.
 * Do not edit by hand: change tokens.ts and run \`pnpm --filter @truckbuck/ui tokens\`.
 */`;

function themeVars(theme: ThemeName, indent: string): string {
  const colors = colorRoles.map((role) => `${indent}--tb-${role}: ${themes[theme][role]};`);
  const elevation = Object.entries(shadows[theme]).map(
    ([name, value]) => `${indent}--tb-shadow-${name}: ${value};`,
  );
  return [`${indent}color-scheme: ${theme};`, ...colors, ...elevation].join("\n");
}

function block(selector: string, body: string, indent = ""): string {
  return `${indent}${selector} {\n${body}\n${indent}}`;
}

export function buildTokensCss(): string {
  const staticVars = [
    `  --tb-font-sans: ${fontFamilies.sans.join(", ")};`,
    `  --tb-font-mono: ${fontFamilies.mono.join(", ")};`,
    ...Object.entries(motion.duration).map(([k, v]) => `  --tb-duration-${k}: ${v};`),
    ...Object.entries(motion.easing).map(([k, v]) => `  --tb-ease-${k}: ${v};`),
    ...Object.entries(zIndex).map(([k, v]) => `  --tb-z-${k}: ${v};`),
    `  --tb-touch-target: ${layout.touchTarget};`,
  ].join("\n");

  const themeMapping = [
    ...colorRoles.map((role) => `  --color-${role}: var(--tb-${role});`),
    ...Object.keys(shadows.light).map((name) => `  --shadow-${name}: var(--tb-shadow-${name});`),
    `  --font-sans: var(--tb-font-sans);`,
    `  --font-mono: var(--tb-font-mono);`,
    ...Object.keys(motion.easing).map((k) => `  --ease-${k}: var(--tb-ease-${k});`),
  ].join("\n");

  const staticTheme = [
    // Reset Tailwind's defaults so only TruckBuck tokens exist: `bg-blue-500`
    // or `shadow-2xl` simply don't compile.
    `  --color-*: initial;`,
    `  --shadow-*: initial;`,
    `  --text-*: initial;`,
    `  --radius-*: initial;`,
    `  --breakpoint-*: initial;`,
    `  --ease-*: initial;`,
    `  --spacing: ${spacingBase};`,
    ...Object.entries(typeScale).flatMap(([name, t]) => [
      `  --text-${name}: ${t.size};`,
      `  --text-${name}--line-height: ${t.lineHeight};`,
      `  --text-${name}--letter-spacing: ${t.tracking};`,
    ]),
    ...Object.entries(radii).map(([k, v]) => `  --radius-${k}: ${v};`),
    ...Object.entries(breakpoints).map(([k, v]) => `  --breakpoint-${k}: ${v};`),
    `  --container-content: ${layout.content};`,
    `  --container-prose: ${layout.prose};`,
  ].join("\n");

  const utilities = [
    ...Object.keys(zIndex).map((k) => block(`@utility z-${k}`, `  z-index: var(--tb-z-${k});`)),
    ...Object.keys(motion.duration).map((k) =>
      block(`@utility duration-${k}`, `  transition-duration: var(--tb-duration-${k});`),
    ),
    block(
      "@utility touch-target",
      "  min-height: var(--tb-touch-target);\n  min-width: var(--tb-touch-target);",
    ),
  ];

  return [
    HEADER,
    "",
    block(':root,\n[data-theme="light"]', themeVars("light", "  ")),
    "",
    block(
      "@media (prefers-color-scheme: dark)",
      block(':root:not([data-theme="light"])', themeVars("dark", "    "), "  "),
    ),
    "",
    block('[data-theme="dark"]', themeVars("dark", "  ")),
    "",
    block(":root", staticVars),
    "",
    block("@theme", staticTheme),
    "",
    block("@theme inline", themeMapping),
    "",
    ...utilities.flatMap((u) => [u, ""]),
  ].join("\n");
}
